using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class F1WildCameraRig {
 public static object Inspect(){return SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Component>(true)).Where(c=>c&&(c.GetType().Name.Contains("Cinemachine")||c.GetType().Name.Contains("Camera"))).Select(c=>new{path=AnimationUtility.CalculateTransformPath(c.transform,null),type=c.GetType().FullName,json=EditorJsonUtility.ToJson(c)}).ToArray();}
 public static object Fix(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var lens=GameObject.Find("Camera").GetComponentsInChildren<Component>(true).Where(c=>c&&c.GetType().Name.Contains("VirtualCamera")).ToArray();int count=0;foreach(var c in lens){var so=new SerializedObject(c);var far=so.FindProperty("m_Lens.FarClipPlane");if(far==null)continue;Undo.RecordObject(c,"1F wilderness view distance");far.floatValue=4500;so.ApplyModifiedProperties();if(PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);count++;}if(count!=1)throw new Exception("Expected one virtual lens");var camera=Camera.main;Undo.RecordObject(camera,"1F wilderness camera distance");camera.farClipPlane=4500;if(PrefabUtility.IsPartOfPrefabInstance(camera))PrefabUtility.RecordPrefabInstancePropertyModifications(camera);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);EditorSceneManager.OpenScene(s.path);var result=new{lensOverrides=count,far=Camera.main.farClipPlane,scope="1F scene lens override only; shared prefabs unchanged",saved=!SceneManager.GetActiveScene().isDirty};File.WriteAllText(Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_WildernessDetail/camera.json"),JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
